"use server";

import { AuthError } from "next-auth";
import { z } from "zod";

import { signIn, signOut } from "@/auth";
import { createUser } from "@/lib/users";

export type AuthFormState = {
  error?: string;
  fieldErrors?: Record<string, string[]>;
};

const signUpSchema = z.object({
  name: z.string().trim().min(1, "Please enter your name"),
  email: z.email("Enter a valid email address"),
  password: z.string().min(8, "Use at least 8 characters"),
});

const signInSchema = z.object({
  email: z.email("Enter a valid email address"),
  password: z.string().min(1, "Enter your password"),
});

/**
 * Only ever redirect within this app. `callbackUrl` arrives from the query
 * string, so an absolute or protocol-relative value would be an open redirect.
 */
function safeRedirect(value: FormDataEntryValue | null): string {
  const url = typeof value === "string" ? value : "";
  if (!url.startsWith("/") || url.startsWith("//")) return "/dashboard";
  return url;
}

export async function signUpAction(
  _prev: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const parsed = signUpSchema.safeParse({
    name: formData.get("name"),
    email: formData.get("email"),
    password: formData.get("password"),
  });

  if (!parsed.success) {
    return { fieldErrors: z.flattenError(parsed.error).fieldErrors };
  }

  const user = await createUser(parsed.data);
  if (!user) {
    return { fieldErrors: { email: ["That email is already registered"] } };
  }

  return credentialsSignIn(
    parsed.data.email,
    parsed.data.password,
    safeRedirect(formData.get("callbackUrl")),
  );
}

export async function signInAction(
  _prev: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const parsed = signInSchema.safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
  });

  if (!parsed.success) {
    return { fieldErrors: z.flattenError(parsed.error).fieldErrors };
  }

  return credentialsSignIn(
    parsed.data.email,
    parsed.data.password,
    safeRedirect(formData.get("callbackUrl")),
  );
}

export async function googleSignInAction(formData: FormData) {
  await signIn("google", { redirectTo: safeRedirect(formData.get("callbackUrl")) });
}

export async function signOutAction() {
  await signOut({ redirectTo: "/" });
}

async function credentialsSignIn(
  email: string,
  password: string,
  redirectTo: string,
): Promise<AuthFormState> {
  try {
    await signIn("credentials", { email, password, redirectTo });
    return {};
  } catch (error) {
    // A successful sign in throws NEXT_REDIRECT, which must reach Next.js.
    // Only genuine auth failures are ours to report.
    if (error instanceof AuthError) {
      return error.type === "CredentialsSignin"
        ? { error: "Wrong email or password" }
        : { error: "Something went wrong signing you in" };
    }
    throw error;
  }
}

