import { redirect } from "next/navigation";

import { signOutAction } from "@/lib/auth-actions";
import { getCurrentUser, listUsers } from "@/lib/users";

export default async function DashboardPage() {
  // The real gate. src/proxy.ts only redirects optimistically; it runs before
  // rendering and must not be the only thing standing between a visitor and
  // this page.
  const me = await getCurrentUser();
  if (!me) redirect("/signin?callbackUrl=%2Fdashboard");

  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-semibold">Dashboard</h1>
          <p className="mt-2 text-sm opacity-70">
            Signed in as {me.name} ({me.email})
          </p>
        </div>

        <form action={signOutAction}>
          <button
            type="submit"
            className="h-9 rounded-full border border-solid border-black/[.12] px-4 text-sm font-medium transition-colors hover:bg-black/[.04] dark:border-white/[.18] dark:hover:bg-white/[.06]"
          >
            Sign out
          </button>
        </form>
      </div>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>
    </main>
  );
}

